reactions.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    const isTranscending = api.findEffectOnToken(reactorToken, "Transcending")?.name == "Transcending";
    const rangeD = 3 + isTranscending * 5;

    function cleanText(html) {
        const doc = new DOMParser().parseFromString(html, "text/html");
        return (doc.body.textContent || "")
            .replace(/’/g, "'")
            .replace(/\s+/g, " ");
    };

    const nhps = reactorToken.actor.items.filter(ownedItem => {
        const system = ownedItem.system;
        if (!system || system.destroyed) return false;

        const tags = system.tags ?? [];
        const hasTag = id => tags.some(tag => tag.lid === id);

        const text = cleanText(
            `${system.description ?? ""} ${system.effect ?? ""}`
        );

        // Some items grant AI in their rules but lack the actual tag.
        const grantsAI = hasTag("tg_ai") || /\b(?:gains?|grants?)\b[^.!?;]*\bAI tag\b/i.test(text);

        const cannotCascade = hasTag("tg_no_cascade") || /\b(?:cannot|can\s+not|can't)\s+(?:enter\s+)?cascade\b/i.test(text);

        return grantsAI && !cannotCascade;
    });

    const damage = 1 + nhps.length + isTranscending * 4;

    await api.executeDamageRoll(reactorToken, null, damage, "energy", "MEMETIC SPARK", {ap: true, targeting: {range: rangeD}});
}

