async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (api.findEffectOnToken(reactorToken, "Transcending")?.name == "Transcending") {return;}
    const ranks = foundry.utils.deepClone(
      item.toObject().system.ranks
    );
    const counter = ranks[2]?.counters?.find(
  c => c.lid === "custom_iconoclast_3_counter"
);

    const value = counter?.value ?? 0;
    if (value == 1) {
        await api.addTokenFlags(reactorToken, {'transcendence': 3})
        await api.applyEffectsToTokens({
        tokens: [reactorToken],
        effectNames: {
            name: "Transcending",
            icon: "systems/lancer/assets/icons/white/orbital.svg",
            isCustom: true
        },
        duration: {
            label: "end",
            turns: 1,
            rounds: 0,
            overrideTurnOriginId: reactorToken.id
        }

    });
    counter.value = 3
    await item.update({ "system.ranks": ranks });
   	return;
}
    counter.value = value - 1
    await item.update({ "system.ranks": ranks });
}

