    const counterId = "custom_iconoclast_3_counter";
    const ranks = foundry.utils.deepClone(item.toObject().system.ranks);
    const rank = ranks?.[2];
    if (!rank) return;
    rank.counters ??= [];

    if (rank.counters.some(counter => counter.lid === counterId)) {
    return;
    }

    rank.counters.push({
    lid: counterId,
    name: "Iconoclast 3",
    min: 1,
    max: 3,
    default_value: 3,
    value: 0
    });

    await item.update({ "system.ranks": ranks });
